# Native download errors include formatted HTTP/curl transport details.
# Avoid treating arbitrary numbers in a URL or a checksum as HTTP status codes.
_HTTP_ERROR = re.compile(
    r"\b(?:https?\s+error\s*:?|status\s+code\s*:|"
    r"requested\s+url\s+returned\s+error\s*:)\s*[45][0-9]{2}\b",
    re.I,
)
_CURL_ERROR = re.compile(r"\bcurl(?:\s+error\s*\(?|#)(\d+)\b", re.I)
_CONNECTION_ERROR = re.compile(
    r"\b(?:timed?\s*out|timeout|connection\s+(?:refused|reset)|"
    r"could\s+not\s+(?:connect|resolve)|couldn't\s+(?:connect|resolve)|"
    r"failed\s+to\s+connect|no\s+route\s+to\s+host|network\s+is\s+unreachable)\b",
    re.I,
)


